void point2ParticleQuad( geometryInS inputs[1], float2 pointSz, float2 screenSize, float4 quadPositionUV[4], 
    float4x4 viewProjInverse, bool isCulled, int normalDir, inout TriangleStream<geometryInS> outStream  ) 
{ 
	 if(isCulled) return; 
    geometryInS outS  = inputs[0]; 
    if(normalDir == 2) outS.Nw = outS.Vw; 
    else if(normalDir == 3) outS.Nw = -outS.Nw; 
    float4 sizeInZ = float4(pointSz.xy  / screenSize.xy, 0, 0) * outS.Pc.w;  
    [unroll] for( int i = 0; i < 4; ++i ) { 
        outS.Pc = inputs[0].Pc + sizeInZ * float4(quadPositionUV[i].xy, 0, 0); 
        outS.Pw = inputs[0].Pw + mul(sizeInZ * float4(quadPositionUV[i].xy, 0, 0), viewProjInverse).xyz; 
        outStream.Append( outS ); 
    } 
    outStream.RestartStrip(); 
}


void point2ParticleQuad( AttribArray<geometryInS>inputs, float2 pointSz, float2 screenSize, float4 quadPositionUV[4], 
	float4x4 viewProjInverse, bool isCulled, int normalDir ) 
{ 
	 if(isCulled) return; 
    geometryInS outS = inputs[0]; 
    if(normalDir == 2) outS.Nw = outS.Vw; 
    else if(normalDir == 3) outS.Nw = -outS.Nw; 
    float4 sizeInZ = float4(pointSz.xy  / screenSize.xy, 0, 0) * outS.Pc.w;  
    for( int i = 0; i < 4; ++i ) { 
        outS.Pc = inputs[0].Pc + sizeInZ * float4(quadPositionUV[i].xy, 0, 0); 
        outS.Pw = inputs[0].Pw + mul(viewProjInverse, sizeInZ * float4(quadPositionUV[i].xy, 0, 0)).xyz; 
        emitVertex( outS ); 
    } 
    restartStrip(); 
}


void point2ParticleQuad(  vec2 pointSz, vec2 screenSize, vec4 quadPositionUV[4], 
	mat4x4 viewProjInverse, bool isCulled, int normalDir ) 
{ 
	 if(isCulled) return; 
    GEO_OUT_struct outS = copyFromGEO_IN(0); 
    if(normalDir == 2) outS.Nw = outS.Vw; 
    else if(normalDir == 3) outS.Nw = -outS.Nw; 
    vec4 sizeInZ = vec4(pointSz.xy  / screenSize.xy, 0, 0) * outS.Pc.w;  
    for( int i = 0; i < 4; ++i ) { 
        outS.Pc = gl_in[0].gl_Position + sizeInZ * vec4(quadPositionUV[i].xy, 0, 0); 
        outS.Pw = GEO_IN[0].Pw + mul(viewProjInverse, sizeInZ * vec4(quadPositionUV[i].xy, 0, 0)).xyz; 
        EmitGeoStruct( outS ); 
    } 
    EndPrimitive(); 
}


void point2ParticleQuad( geometryInS inputs[1], float2 pointSz, float2 screenSize, float4 quadPositionUV[4], 
    float4x4 viewProjInverse, bool isCulled, int normalDir, inout TriangleStream<geometryInS> outStream  ) 
{ 
	 if(isCulled) return; 
    geometryInS outS  = inputs[0]; 
    if(normalDir == 2) outS.Nw = outS.Vw; 
    else if(normalDir == 3) outS.Nw = -outS.Nw; 
    float4 sizeInZ = float4(pointSz.xy  / screenSize.xy, 0, 0) * outS.Pc.w;  
    [unroll] for( int i = 0; i < 4; ++i ) { 
        outS.Pc = inputs[0].Pc + sizeInZ * float4(quadPositionUV[i].xy, 0, 0); 
        outS.Pw = inputs[0].Pw + mul(sizeInZ * float4(quadPositionUV[i].xy, 0, 0), viewProjInverse).xyz; 
        outStream.Append( outS ); 
    } 
    outStream.RestartStrip(); 
}
